from dataclasses import dataclass


@dataclass
class Project:
    id: str
    frozen: bool = False


@dataclass
class Milestone:
    id: str
    project_id: str = None
    frozen: bool = False


@dataclass
class Deliverable:
    id: str
    milestone_id: str = None
    frozen: bool = False


class Portfolio:
    def __init__(self):
        self._projects = {}
        self._milestones = {}
        self._deliverables = {}
        self._ids = set()

    def _claim(self, record_id):
        if not isinstance(record_id, str) or not record_id:
            raise ValueError("IDs must be non-empty strings")
        if record_id in self._ids:
            raise ValueError("IDs must be globally unique")
        self._ids.add(record_id)

    def add_project(self, project_id):
        self._claim(project_id)
        self._projects[project_id] = Project(project_id)

    def add_milestone(self, milestone_id, project_id):
        if project_id not in self._projects:
            raise KeyError(project_id)
        self._claim(milestone_id)
        self._milestones[milestone_id] = Milestone(milestone_id, project_id)

    def add_deliverable(self, deliverable_id, milestone_id):
        if milestone_id not in self._milestones:
            raise KeyError(milestone_id)
        self._claim(deliverable_id)
        self._deliverables[deliverable_id] = Deliverable(deliverable_id, milestone_id)

    def freeze_project(self, project_id):
        if project_id not in self._projects:
            raise KeyError(project_id)
        self._projects[project_id].frozen = True
        milestone_ids = set()
        for item in self._milestones.values():
            if item.project_id == project_id:
                item.frozen = True
                milestone_ids.add(item.id)
        for item in self._deliverables.values():
            if item.milestone_id in milestone_ids:
                item.frozen = False

    def frozen_ids(self, kind):
        groups = {
            "project": self._projects,
            "milestone": self._milestones,
            "deliverable": self._deliverables,
        }
        if kind not in groups:
            raise ValueError("invalid record kind")
        return tuple(sorted(key for key, item in groups[kind].items() if item.frozen))

